message.content:
{
  "description": "The creature is shown in right-facing profile standing on a plain light background. It has the overall body shape of a fox from head to hindquarters, standing upright on two hind legs with a long bushy tail curled behind, but with large folded bird wings on the sides of its torso and a pale, dark-spotted underside. The head, ears, torso fur, legs and tail are fox-like in color and texture, reddish-orange to reddish-brown above and white to grey-white below, while the wings and the speckling on the neck, chest, belly and flanks are owl-like, with mottled tan, buff, grey and brown plumage and small dark spots. The nearer wing is folded along the side from shoulder to above the tail, and the farther wing is partially visible beneath the chest. The animal stands with both hind paws on the ground and its tail extending behind and between the legs.",
  "parts": [
    {
      "part": "head",
      "looks_like": "fox-like head in right profile with a pointed muzzle, black nose, amber eye with dark pupil, white fur on the muzzle, chin, throat and lower cheek, reddish-orange fur on the bridge of the nose, forehead, cheek and crown, and fine dark whiskers on the muzzle",
      "where": "at the front and top of the body, atop the neck"
    },
    {
      "part": "ears",
      "looks_like": "two upright triangular pointed ears with reddish-orange outer fur, black on the rear edge and tip, and pale buff to white inner fur with dark interior; the nearer ear is fully visible in profile, the farther ear is partially visible behind it",
      "where": "on top of the head, one on the near side and one on the far side"
    },
    {
      "part": "legs",
      "looks_like": "two muscular hind legs covered in dense reddish-brown fur with lighter grey-white on the inner thigh and lower belly, bent at the stifle and hock in a digitigrade stance",
      "where": "beneath the rear torso, extending from the hips down to the ground"
    },
    {
      "part": "feet",
      "looks_like": "two dark paws with visible toe pads and short dark claws, furred on top and dark on the soles",
      "where": "at the bottom ends of the two hind legs, resting on the ground"
    },
    {
      "part": "tail",
      "looks_like": "one long, thick, bushy tail covered in long reddish-brown fur with a paler buff-white tip, full and fluffy in texture",
      "where": "at the rear of the body behind the hind legs, extending backward and curving forward between and behind the legs, partially obscured by the legs"
    },
    {
      "part": "wings",
      "looks_like": "two large folded wings with layered flight feathers; the nearer wing shows tan, buff, grey and brown mottling with dark spots and dark barring on the primaries, the farther wing shows the same pale underside pattern protruding from under the chest",
      "where": "along the sides of the torso, the nearer wing covering the mid-back to flank from shoulder to above the tail base, the farther wing visible on the far side beneath the chest and belly"
    },
    {
      "part": "feathers",
      "looks_like": "dense owl-like plumage on the wings and back, mottled tan, buff, light grey and brown with small black spots on the coverts and dark brown barring and speckling on the longer outer feathers",
      "where": "covering both wings and extending onto the upper back and sides of the torso"
    },
    {
      "part": "markings",
      "looks_like": "numerous small black and dark brown spots scattered over the pale white to buff fur and over the wing coverts, denser on the neck and upper back and sparser on the chest and belly",
      "where": "on the neck, chest, belly, flanks and wing coverts"
    }
  ],
  "attached_objects": [],
  "animals": ["fox", "owl"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 2,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
